package br.com.admeclesial.application.projeto;
import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class DestinacaoContribuicaoApplicationServiceTest { @Mock DestinacaoContribuicaoRepository repo; @Mock ContribuicaoRepository contrib; @Mock CentroCustoRepository centros;
@Test void deveCriarDestinacaoEspecifica(){var c=new Contribuicao();setId(c,1L);c.setValor(new BigDecimal("500"));c.setOrganizacaoEclesialId(10L);var u=UUID.randomUUID();when(contrib.findByUuid(u)).thenReturn(Optional.of(c));when(repo.sumValorPorContribuicao(1L)).thenReturn(BigDecimal.ZERO);when(repo.save(any())).thenAnswer(i->i.getArgument(0));var s=new DestinacaoContribuicaoApplicationService(repo,contrib,centros);var d=s.criar(new DestinacaoContribuicaoRequest(u,null,TipoDestinacaoContribuicao.FINALIDADE_ESPECIFICA,"Telhado",new BigDecimal("500"),true));assertEquals(TipoDestinacaoContribuicao.FINALIDADE_ESPECIFICA,d.getTipo());assertEquals(new BigDecimal("500"),d.getValor());}
@Test void naoPermiteDestinacaoAcimaDaContribuicao(){var c=new Contribuicao();setId(c,1L);c.setValor(new BigDecimal("100"));var u=UUID.randomUUID();when(contrib.findByUuid(u)).thenReturn(Optional.of(c));var s=new DestinacaoContribuicaoApplicationService(repo,contrib,centros);assertThrows(IllegalArgumentException.class,()->s.criar(new DestinacaoContribuicaoRequest(u,null,TipoDestinacaoContribuicao.FINALIDADE_ESPECIFICA,"X",new BigDecimal("101"),true)));}
private static void setId(Object o,long id){try{var f=o.getClass().getDeclaredField("id");f.setAccessible(true);f.set(o,id);}catch(Exception e){throw new RuntimeException(e);}} }
